-- O catálogo da matriz de habilidades sai do código e vira cadastro do coordenador.
-- Equipamentos e habilidades entram com o mesmo id que as marcações e notas já usavam
-- (chave do equipamento e H1…H222), então nada do que está gravado muda.

CREATE TABLE "MatrixEquipment" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "position" INTEGER NOT NULL,
    "archived" BOOLEAN NOT NULL DEFAULT false,

    CONSTRAINT "MatrixEquipment_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "MatrixEquipment_name_key" ON "MatrixEquipment"("name");

CREATE TABLE "MatrixSkill" (
    "id" TEXT NOT NULL,
    "equipmentId" TEXT NOT NULL,
    "subgroup" TEXT NOT NULL,
    "text" TEXT NOT NULL,
    "level" TEXT NOT NULL,
    "position" INTEGER NOT NULL,
    "archived" BOOLEAN NOT NULL DEFAULT false,

    CONSTRAINT "MatrixSkill_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "MatrixSkill_equipmentId_idx" ON "MatrixSkill"("equipmentId");

ALTER TABLE "MatrixSkill" ADD CONSTRAINT "MatrixSkill_equipmentId_fkey" FOREIGN KEY ("equipmentId") REFERENCES "MatrixEquipment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;



-- Marcação ou nota com chave fora do catálogo não deveria existir (a API só aceitava o catálogo); se houver, sai antes das chaves estrangeiras.
DELETE FROM "MemberMatrixEquipment" WHERE "equipment" NOT IN (SELECT "id" FROM "MatrixEquipment");
DELETE FROM "MemberSkill" WHERE "skillId" NOT IN (SELECT "id" FROM "MatrixSkill");

ALTER TABLE "MemberMatrixEquipment" RENAME COLUMN "equipment" TO "equipmentId";

CREATE INDEX "MemberMatrixEquipment_equipmentId_idx" ON "MemberMatrixEquipment"("equipmentId");
CREATE INDEX "MemberSkill_skillId_idx" ON "MemberSkill"("skillId");

ALTER TABLE "MemberMatrixEquipment" ADD CONSTRAINT "MemberMatrixEquipment_equipmentId_fkey" FOREIGN KEY ("equipmentId") REFERENCES "MatrixEquipment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MemberSkill" ADD CONSTRAINT "MemberSkill_skillId_fkey" FOREIGN KEY ("skillId") REFERENCES "MatrixSkill"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
